// Split the thread body into individual tweets and POST a real Buffer thread.
// Source format (from the parser): "Tweet 1/N\n<body>\n\n---\n\nTweet 2/N\n<body>..."
const row = $input.item.json;
const raw = String(row.content || '');
const tweets = raw
  .split(/\n-{3,}\n/)
  .map((part) => part.replace(/^\s*Tweet\s+\d+\s*\/\s*\d+\s*\n/i, '').trim())
  .filter((t) => t.length > 0);
if (tweets.length === 0) {
  throw new Error(`Thread row ${row.id} (${row.fileRef}) parsed to 0 tweets`);
}
for (const t of tweets) {
  if (t.length > 280) {
    throw new Error(`Thread row ${row.id} has a tweet over 280 chars: ${t.length}`);
  }
}
const scheduledAt = Math.floor(new Date(row.scheduledFor).getTime() / 1000);
const params = new URLSearchParams();
params.append('access_token', String(process.env.BUFFER_ACCESS_TOKEN || ''));
params.append('profile_ids[]', String(process.env.BUFFER_PROFILE_X || ''));
params.append('scheduled_at', String(scheduledAt));
params.append('text', tweets[0]);
for (let i = 1; i < tweets.length; i += 1) {
  // Buffer's threading parameter: each subsequent tweet is appended via thread[][text].
  params.append('thread[][text]', tweets[i]);
}
const resp = await fetch('https://api.bufferapp.com/1/updates/create.json', {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: params.toString(),
});
const body = await resp.json().catch(() => ({}));
if (!resp.ok || body.success === false) {
  throw new Error(`Buffer thread schedule failed for ${row.fileRef}: ${resp.status} ${JSON.stringify(body).slice(0, 300)}`);
}
return { json: { tweetCount: tweets.length, bufferUpdateId: body && body.updates && body.updates[0] && body.updates[0].id, bufferResponse: body } };

